<?php declare(strict_types=1); namespace Annam; $title='Your cart · '.$store->name(); ?>
<section class="wrap php-store-section"><h1>Your cart</h1><?php if (!$quote['lines']): ?><p>Your cart is empty.</p><a class="btn btn-primary" href="/menu/">Browse meals →</a><?php else: ?>
<?php if (($quote['cart']['kind']??'')==='scheduled'): ?><p><?= e($quote['cart']['date']) ?> · <?= e(implode(' + ',array_map('ucfirst',$quote['meal_keys']))) ?></p><?php endif; ?><div class="php-cart-grid"><section class="php-white php-cart-lines"><?php foreach ($quote['lines'] as $line): ?><article><div><h3><?= e($line['item']['name']) ?></h3><p><?= e($line['quantity']) ?> × <?= Money::display($line['unit']) ?></p></div><b><?= Money::display($line['amount']) ?></b><form method="post" action="/cart/update/"><?= csrf() ?><input type="hidden" name="item_id" value="<?= e($line['key']) ?>"><label>Quantity<input type="number" name="quantity" min="0" max="99" value="<?= e($line['quantity']) ?>" style="width:75px"></label><button class="btn">Update</button></form><form method="post" action="/cart/remove/"><?= csrf() ?><input type="hidden" name="item_id" value="<?= e($line['key']) ?>"><button class="btn" type="submit">Remove</button></form></article><?php endforeach; ?><form method="post" action="/cart/clear/"><?= csrf() ?><button class="btn" type="submit">Clear cart</button></form></section><section class="php-white php-cart-summary"><h2>Delivery check</h2><?php if(($quote['cart']['kind']??'')==='courier'): ?><p>Local Chennai delivery uses the selected area's charge. For other destinations, courier charges are confirmed separately after dispatch.</p><?php endif; ?><form method="post"><?= csrf() ?><?php if(($quote['cart']['kind']??'')==='courier'): ?><label>City<input name="city" required></label><label>Country<input name="country" value="India" required></label><?php endif; ?><label>Pincode <input name="pincode" value="<?= e($_POST['pincode']??'') ?>" pattern="[1-9][0-9]{5}" maxlength="6" inputmode="numeric" required></label><label>Area (when your pincode has multiple areas)<select name="area_id"><option value="">Select automatically</option><?php foreach ($areas as $area): ?><option value="<?= e($area['id']) ?>" <?= (string)($_POST['area_id']??'')===(string)$area['id']?'selected':'' ?>><?= e($area['pincode'].' · '.$area['area_name']) ?></option><?php endforeach; ?></select></label><button class="btn" type="submit">Check delivery</button></form><?php if ($error): ?><p class="php-error" role="alert"><?= e($error) ?></p><?php endif; ?><p class="php-total"><span>Items subtotal</span><b><?= Money::display($quote['subtotal']) ?></b></p><?php if ($delivery): ?><p class="php-total"><span>Delivery charge</span><b><?= Money::display($delivery['fee']) ?></b></p><p class="php-total"><span>Total before tax review</span><b><?= Money::display($quote['subtotal']+$delivery['fee']) ?></b></p><?php if($delivery['deferred']??false): ?><p><?= e(Delivery::COURIER) ?></p><?php else: ?><p class="php-success">This order meets the area minimum. One delivery charge applies.</p><?php endif; ?><?php endif; ?><a class="btn btn-primary" href="/checkout/">Checkout →</a></section></div><?php endif; ?></section>
